"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

from dataclasses import dataclass

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


def _get_header(headers: dict[str, str], name: str) -> str | None:
    """Get a header value case-insensitively."""
    for key, value in headers.items():
        if key.lower() == name.lower():
            return value
    return None


def _parse_cache_control(value: str) -> dict[str, str | None]:
    """Parse Cache-Control header into directives."""
    directives = {}
    if not value:
        return directives

    # Handle quoted values that may contain commas
    i = 0
    current_directive = ""
    in_quotes = False

    while i < len(value):
        char = value[i]

        if char == '"' and (i == 0 or value[i - 1] != '\\'):
            in_quotes = not in_quotes
            current_directive += char
        elif char == ',' and not in_quotes:
            directive_str = current_directive.strip()
            if directive_str:
                _parse_single_directive(directive_str, directives)
            current_directive = ""
        else:
            current_directive += char

        i += 1

    # Handle last directive
    directive_str = current_directive.strip()
    if directive_str:
        _parse_single_directive(directive_str, directives)

    return directives


def _parse_single_directive(directive_str: str, directives: dict) -> None:
    """Parse a single directive and add to directives dict."""
    if '=' not in directive_str:
        name = directive_str.strip().lower()
        directives[name] = None
    else:
        parts = directive_str.split('=', 1)
        name = parts[0].strip().lower()
        value = parts[1].strip()

        # Remove quotes if present
        if value.startswith('"') and value.endswith('"'):
            value = value[1:-1]

        directives[name] = value


def _parse_imf_fixdate(date_str: str) -> int:
    """Parse an IMF-fixdate and return epoch seconds."""
    date_str = date_str.strip()

    if len(date_str) != 29:
        raise HeaderError(f"Invalid date format: {date_str}")

    day_names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    month_names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

    # Parse: "Mon, 01 Jun 2026 12:00:00 GMT"
    # Indices: 0-2: day, 3: comma, 4: space, 5-6: day-of-month, 7: space,
    #          8-10: month, 11: space, 12-15: year, 16: space, 17-24: time, 25: space, 26-28: GMT

    day_name = date_str[0:3]
    if day_name not in day_names:
        raise HeaderError(f"Invalid day name: {day_name}")

    if date_str[3] != ",":
        raise HeaderError("Invalid date format")

    if date_str[4] != " ":
        raise HeaderError("Invalid date format")

    day = date_str[5:7]
    if not day.isdigit():
        raise HeaderError("Invalid day of month")
    day_int = int(day)

    if date_str[7] != " ":
        raise HeaderError("Invalid date format")

    month_name = date_str[8:11]
    if month_name not in month_names:
        raise HeaderError(f"Invalid month name: {month_name}")
    month_int = month_names.index(month_name) + 1

    if date_str[11] != " ":
        raise HeaderError("Invalid date format")

    year = date_str[12:16]
    if not year.isdigit():
        raise HeaderError("Invalid year")
    year_int = int(year)

    if date_str[16] != " ":
        raise HeaderError("Invalid date format")

    time_str = date_str[17:25]
    time_parts = time_str.split(":")
    if len(time_parts) != 3 or not all(p.isdigit() for p in time_parts):
        raise HeaderError("Invalid time")
    hour = int(time_parts[0])
    minute = int(time_parts[1])
    second = int(time_parts[2])

    if date_str[25] != " ":
        raise HeaderError("Invalid date format")

    if date_str[26:29] != "GMT":
        raise HeaderError("Invalid GMT suffix")

    # Validate ranges
    if not (1 <= day_int <= 31):
        raise HeaderError("Invalid day of month")
    if not (0 <= hour <= 23):
        raise HeaderError("Invalid hour")
    if not (0 <= minute <= 59):
        raise HeaderError("Invalid minute")
    if not (0 <= second <= 60):  # Allow 60 for leap seconds
        raise HeaderError("Invalid second")

    # Check if it's a valid date (basic check)
    try:
        from datetime import datetime
        dt = datetime(year_int, month_int, day_int, hour, minute, second)
        # Convert to epoch seconds
        import calendar
        return int(calendar.timegm(dt.timetuple()))
    except (ValueError, OverflowError):
        raise HeaderError(f"Invalid date: {date_str}")


def _get_numeric_directive(directives: dict[str, str | None], name: str) -> int | None:
    """Get a numeric directive value, or None if not present or invalid."""
    value = directives.get(name.lower())
    if value is None:
        return None
    if value.isdigit():
        return int(value)
    return None


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""

    # Parse response and request Cache-Control
    response_cc_str = _get_header(response_headers, "Cache-Control") or ""
    request_cc_str = _get_header(request_headers, "Cache-Control") or ""

    response_cc = _parse_cache_control(response_cc_str)
    request_cc = _parse_cache_control(request_cc_str)

    # Get Date header
    date_str = _get_header(response_headers, "Date")
    if date_str:
        response_date = _parse_imf_fixdate(date_str)
    else:
        response_date = response_time

    # Get Age header
    age_str = _get_header(response_headers, "Age")
    if age_str and age_str.isdigit():
        age = int(age_str)
    else:
        age = 0

    # Calculate current_age per RFC 9111 §4.2.3
    response_delay = response_time - request_time
    apparent_age = max(0, response_time - response_date)
    corrected_age = age + response_delay
    initial_age = max(apparent_age, corrected_age)
    resident_time = now - response_time
    current_age = initial_age + resident_time

    # Calculate freshness_lifetime
    # Rule 1: response s-maxage
    s_maxage = _get_numeric_directive(response_cc, "s-maxage")
    if s_maxage is not None:
        freshness_lifetime = s_maxage
    else:
        # Rule 2: response max-age
        max_age = _get_numeric_directive(response_cc, "max-age")
        if max_age is not None:
            freshness_lifetime = max_age
        else:
            # Rule 3: Expires header
            expires_str = _get_header(response_headers, "Expires")
            if expires_str:
                try:
                    expires = _parse_imf_fixdate(expires_str)
                    freshness_lifetime = max(0, expires - response_date)
                except HeaderError:
                    # Invalid Expires, skip to next rule
                    freshness_lifetime = None
            else:
                freshness_lifetime = None

            if freshness_lifetime is None:
                # Rule 4: Last-Modified header (heuristic)
                last_modified_str = _get_header(response_headers, "Last-Modified")
                if last_modified_str:
                    try:
                        last_modified = _parse_imf_fixdate(last_modified_str)
                        freshness_lifetime = max(0, (response_date - last_modified) // 10)
                    except HeaderError:
                        freshness_lifetime = 0
                else:
                    # Rule 5: No information
                    freshness_lifetime = 0

    # Tighten with request max-age
    request_max_age = _get_numeric_directive(request_cc, "max-age")
    if request_max_age is not None:
        freshness_lifetime = min(freshness_lifetime, request_max_age)

    # Determine verdict
    # Check 1: Must-revalidate directives
    must_revalidate_flags = ["no-store", "no-cache", "must-revalidate"]
    for flag in must_revalidate_flags:
        if flag in response_cc or flag in request_cc:
            return Result(MUST_REVALIDATE, current_age, freshness_lifetime)

    # Check 2: Freshness based on min-fresh
    min_fresh_value = _get_numeric_directive(request_cc, "min-fresh")
    min_fresh = min_fresh_value if min_fresh_value is not None else 0

    if freshness_lifetime > current_age + min_fresh:
        return Result(FRESH, current_age, freshness_lifetime)

    # Check 3: max-stale
    if "max-stale" in request_cc:
        max_stale_value = request_cc.get("max-stale")
        if max_stale_value is None:
            # Written without value, always fresh
            return Result(FRESH, current_age, freshness_lifetime)
        elif max_stale_value.isdigit():
            # Written as max-stale=N
            max_stale_n = int(max_stale_value)
            if current_age - freshness_lifetime <= max_stale_n:
                return Result(FRESH, current_age, freshness_lifetime)

    # Check 4: Otherwise stale
    return Result(STALE, current_age, freshness_lifetime)
